import React from "react";
import { Link, graphql } from "gatsby";
import { ArrowLeft } from "lucide-react";
import Layout from "../components/layout/layout";
import PostCard from "../components/postCard";
import { SEO as Seo } from "../components/seo";
import { tagPath } from "../lib/content.cjs";
// Topics that appear alongside this one, most shared first.
function relatedTopics(nodes, tag, totals) {
  const shared = new Map();
  for (const node of nodes)
    for (const other of node.frontmatter.tags || [])
      if (other !== tag) shared.set(other, (shared.get(other) || 0) + 1);
  return [...shared.keys()]
    .sort((a, b) => shared.get(b) - shared.get(a) || a.localeCompare(b))
    .slice(0, 6)
    .map((name) => ({ name, count: totals.get(name) || 0 }));
}
export default function TagPage({ data, pageContext: { tag } }) {
  const totals = new Map(data.topics.group.map((topic) => [topic.fieldValue, topic.totalCount]));
  const related = relatedTopics(data.allMdx.nodes, tag, totals);
  return (
    <Layout>
      <section className="page-intro">
        <Link className="back-link" to="/tags/">
          <ArrowLeft size={15} aria-hidden="true" /> All topics
        </Link>
        <h1>{tag}</h1>
        <p>
          {data.allMdx.totalCount}{" "}
          {data.allMdx.totalCount === 1 ? "note" : "notes"} from the workbench.
        </p>
      </section>
      {related.length > 0 && (
        <nav className="related-topics" aria-label="Related topics">
          <span>Related topics</span>
          <ul className="topic-nav">
            {related.map((topic) => (
              <li key={topic.name}>
                <Link className="topic-chip" to={tagPath(topic.name)}>
                  {topic.name}
                  <span>
                    {topic.count}
                    <span className="sr-only"> {topic.count === 1 ? "article" : "articles"}</span>
                  </span>
                </Link>
              </li>
            ))}
          </ul>
        </nav>
      )}
      <PostCard nodes={data.allMdx.nodes} />
    </Layout>
  );
}
export const query = graphql`
  query TaggedArticles($tag: String!) {
    allMdx(
      sort: { frontmatter: { date: DESC } }
      filter: { frontmatter: { tags: { in: [$tag] } } }
    ) {
      totalCount
      nodes {
        ...PostCardData
      }
    }
    topics: allMdx {
      group(field: { frontmatter: { tags: SELECT } }) {
        fieldValue
        totalCount
      }
    }
  }
`;
export const Head = ({ pageContext: { tag } }) => (
  <Seo
    title={`${tag} articles`}
    description={`Practical ${tag} tutorials and project notes by Ahmad Roshanfar.`}
    pathname={tagPath(tag)}
  />
);
